def count_islands_eight_connected(grid: List[str]) -> int:
    rows = len(grid)
    seen = set()
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] != '#' or (r, c) in seen:
                continue
            count += 1
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < rows and 0 <= nc < len(grid[nr])
                                and grid[nr][nc] == '#' and (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
    return count

