def connected_region_size(grid: List[List[int]], r: int, c: int) -> int:
    rows = len(grid)
    if not (0 <= r < rows and 0 <= c < len(grid[r])):
        return 0
    target = grid[r][c]
    seen = {(r, c)}
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()
        for nr, nc in ((cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)):
            if (0 <= nr < rows and 0 <= nc < len(grid[nr])
                    and (nr, nc) not in seen and grid[nr][nc] == target):
                seen.add((nr, nc))
                stack.append((nr, nc))
    return len(seen)

