def largest_all_ones_square(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    cols = len(grid[0])
    prev = [0] * (cols + 1)
    best = 0
    for row in grid:
        cur = [0] * (cols + 1)
        for c in range(cols):
            if row[c] == 1:
                cur[c + 1] = 1 + min(prev[c], prev[c + 1], cur[c])
                best = max(best, cur[c + 1])
        prev = cur
    return best

