def clamped_walk_endpoint(moves: str, rows: int, cols: int, start: Tuple[int, int] = (0, 0)) -> Tuple[int, int]:
    deltas = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
    r, c = start
    for move in moves:
        if move not in deltas:
            continue
        dr, dc = deltas[move]
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            r, c = nr, nc
    return (r, c)

