def classify_point_in_polygon(polygon: List[Tuple[int, int]], point: Tuple[int, int]) -> str:
    px, py = point
    n = len(polygon)
    inside = False
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        cross = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
        if cross == 0 and min(x1, x2) <= px <= max(x1, x2) and min(y1, y2) <= py <= max(y1, y2):
            return 'boundary'
        if (y1 > py) != (y2 > py):
            # x-coordinate of the edge at height py compared with px, kept in integers
            lhs = (px - x1) * (y2 - y1)
            rhs = (x2 - x1) * (py - y1)
            if (y2 - y1) > 0:
                crosses = lhs < rhs
            else:
                crosses = lhs > rhs
            if crosses:
                inside = not inside
    return 'inside' if inside else 'outside'

